  "status": "SUPPORTED",
  "claim": {
    "component_id": "C023.component",
    "value": "A reproducible decrease in missing attachments after responsibility ambiguity is removed would increase support for ambiguity contributing to missing attachments.",
    "scope": "A conditional increase in causal support, not a claim of demonstrated causation or an observed decrease.",
    "provenance": {
      "refs": [
        {
          "source_id": "P018",
          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "P018 directly supplies the reproducibility condition and the bounded increase in causal support."
    }
  },
  "signal_basis": {
    "component_id": "C023.signal_basis",
    "value": "Make attachment responsibility explicit, compare missing-attachment frequency across comparable covered orders using consistent inspection intervals, and observe a reproducible reduction. Recurrence under restored ambiguity and improvement under restored clarity in safe simulation provide optional additional evidence.",
    "scope": "Prospective attachment outcomes, with other workflow conditions held unchanged where feasible and concurrent changes logged. Alternative causes remain possible; simulation does not establish live-effect magnitude, and the result does not explain every historical gap.",
